1	package com.example.starter.valve;
2	
3	import com.example.starter.idempotent.IdempotencyService;
4	import com.example.starter.idempotent.ReplayResult;
5	import com.example.starter.station.Station;
6	import com.example.starter.station.StationRepository;
7	import com.example.starter.web.ResourceNotFoundException;
8	import com.example.starter.web.dto.LockConfirmRequest;
9	import com.example.starter.web.dto.LockConfirmResponse;
10	import org.springframework.stereotype.Service;
11	
12	/**
13	 * 异常处置：锁阀（LOCK）与复开（REOPEN）双人确认。
14	 *
15	 * <ul>
16	 *   <li>两名操作人工号不同方为有效确认；单人操作（两人同号）不生效，
17	 *       阀门与告警状态保持不变，仅留 PENDING 工单；</li>
18	 *   <li>复开生效时，加注阀解锁、告警解除、连续越限计数归零在同一事务完成；</li>
19	 *   <li>全部状态更新以 valve_state 行锁串行化。</li>
20	 * </ul>
21	 */
22	@Service
23	public class LockService {
24	
25	    private final StationRepository stationRepository;
26	    private final ValveStateRepository valveStateRepository;
27	    private final LockOrderRepository lockOrderRepository;
28	    private final IdempotencyService idempotencyService;
29	
30	    public LockService(StationRepository stationRepository,
31	                       ValveStateRepository valveStateRepository,
32	                       LockOrderRepository lockOrderRepository,
33	                       IdempotencyService idempotencyService) {
34	        this.stationRepository = stationRepository;
35	        this.valveStateRepository = valveStateRepository;
36	        this.lockOrderRepository = lockOrderRepository;
37	        this.idempotencyService = idempotencyService;
38	    }
39	
40	    public LockConfirmResponse confirm(LockConfirmRequest request) {
41	        Station station = stationRepository.findByCode(request.stationCode())
42	                .orElseThrow(() -> new ResourceNotFoundException(
43	                        "station not found: " + request.stationCode()));
44	        ReplayResult<LockConfirmResponse> replay = idempotencyService.run(
45	                request.requestId(), station.id(), "LOCK_CONFIRM", request, 200,
46	                () -> doConfirm(station, request), LockConfirmResponse.class);
47	        return replay.result();
48	    }
49	
50	    private LockConfirmResponse doConfirm(Station station, LockConfirmRequest request) {
51	        boolean twoOperators = !request.firstOperator().equals(request.secondOperator());
52	
53	        ValveState state = valveStateRepository.selectForUpdate(station.id());
54	
55	        if (!twoOperators) {
56	            // 单人操作（两签名同号）不生效：仅登记 PENDING 工单，阀门状态不变
57	            lockOrderRepository.insert(station.id(), request.action(), "PENDING",
58	                    request.firstOperator(), null, null);
59	            return new LockConfirmResponse(false, state.injectionLocked(),
60	                    state.alarmActive(), false);
61	        }
62	
63	        if ("LOCK".equals(request.action())) {
64	            valveStateRepository.updateState(station.id(), true, true, state.breachCount(),
65	                    state.currentInjectionRateMgM3(), state.currentPressureMpa());
66	            lockOrderRepository.insert(station.id(), "LOCK", "CONFIRMED",
67	                    request.firstOperator(), request.secondOperator(), null);
68	            return new LockConfirmResponse(true, true, true, false);
69	        }
70	
71	        // REOPEN：复开与告警解除同一事务完成，越限计数归零
72	        valveStateRepository.updateState(station.id(), false, false, 0,
73	                state.currentInjectionRateMgM3(), state.currentPressureMpa());
74	        lockOrderRepository.insert(station.id(), "REOPEN", "CONFIRMED",
75	                request.firstOperator(), request.secondOperator(), null);
76	        return new LockConfirmResponse(true, false, false, false);
77	    }
78	}
