9	 * 加注阀状态仓储：所有读取均加行锁（FOR UPDATE），保证并发裁决串行化。
10	 */
11	@Repository
12	public class ValveStateRepository {
13	
14	    private final JdbcTemplate jdbc;
15	
16	    public ValveStateRepository(JdbcTemplate jdbc) {
17	        this.jdbc = jdbc;
18	    }
19	
20	    /**
21	     * 事务内行级锁定读取门站阀门状态。
22	     */
23	    public ValveState selectForUpdate(Long stationId) {
24	        return jdbc.query("""
25	                        SELECT station_id, injection_locked, alarm_active, breach_count,
26	                               current_injection_rate_mg_m3, current_pressure_mpa
27	                        FROM valve_state WHERE station_id = ? FOR UPDATE
28	                        """,
29	                        rs -> {
30	                            if (!rs.next()) {
31	                                return null;
32	                            }
33	                            return new ValveState(
34	                                    rs.getLong("station_id"),
35	                                    rs.getBoolean("injection_locked"),
36	                                    rs.getBoolean("alarm_active"),
37	                                    rs.getInt("breach_count"),
38	                                    rs.getBigDecimal("current_injection_rate_mg_m3"),
39	                                    rs.getBigDecimal("current_pressure_mpa"));
40	                        },
41	                        stationId);
42	    }
43	
44	    /**
45	     * 不加锁读取，用于重放后返回当前阀门态以外的只读场景。
46	     */
47	    public ValveState find(Long stationId) {
48	        return jdbc.query("""
49	                        SELECT station_id, injection_locked, alarm_active, breach_count,
50	                               current_injection_rate_mg_m3, current_pressure_mpa
51	                        FROM valve_state WHERE station_id = ?
52	                        """,
53	                        rs -> rs.next() ? new ValveState(
54	                                rs.getLong("station_id"),
55	                                rs.getBoolean("injection_locked"),
56	                                rs.getBoolean("alarm_active"),
57	                                rs.getInt("breach_count"),
58	                                rs.getBigDecimal("current_injection_rate_mg_m3"),
59	                                rs.getBigDecimal("current_pressure_mpa")) : null,
60	                        stationId);
61	    }
62	
63	    public void updateState(Long stationId, boolean locked, boolean alarm, int breachCount,
64	                            BigDecimal injectionRateMgM3, BigDecimal pressureMpa) {
65	        jdbc.update("""
66	                        UPDATE valve_state
67	                        SET injection_locked = ?, alarm_active = ?, breach_count = ?,
68	                            current_injection_rate_mg_m3 = ?, current_pressure_mpa = ?,
69	                            updated_at = CURRENT_TIMESTAMP
70	                        WHERE station_id = ?
71	                        """,
72	                locked, alarm, breachCount, injectionRateMgM3, pressureMpa, stationId);
73	    }
74	
75	    /**
76	     * 仅更新加注速率与压力（压力联动使用），锁阀/告警/越限计数保持不变。
